
select * from customer limit 10;

--Q1. What is the total revenue generated by male vs. female customers?
Select gender,sum(purchase_amount) from customer group by gender;

--Q2. Which customers used a discount but still spent more than the average purchase amount? 
Select * from customer where discount_applied='Yes' and purchase_amount>(select avg(purchase_amount)from customer);

-- Q3. Which are the top 5 products with the highest average review rating?
select item_purchased, round(avg(review_rating::numeric),2) as avg_rating from customer group by item_purchased order by avg_rating desc limit 5;

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping. 
select shipping_type, round(avg(purchase_amount::numeric),2) as avg_purc from customer group by item_purchased order by avg_rating desc limit 5;


--Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.
Select subscription_status,sum(purchase_amount),round(avg(purchase_amount),2) from customer group by subscription_status;

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased,sum(case when discount_applied='Yes' then 1 else 0 end)*100/count(*) as percent_purchase from customer group by item_purchased order by percent_purchase desc limit 5

--Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment. 
with customer_tab as(select customer_id, previous_purchases, (case
when previous_purchases = 1 then 'New'
when previous_purchases between 2 and 10 then 'Returning'
else 'Loyal'
end) as cust_segment from customer)
select cust_segment, count(*) from customer_tab group by cust_segment

--Q8. What are the top 3 most purchased products within each category? 
with item_count as(
select category,item_purchased,count(*)as quantity, row_number() over (partition by category order by count(*) desc) as item_rank from customer group by category,item_purchased )
select  category,item_purchased, quantity, item_rank from item_count where item_rank<=3

--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select(case when previous_purchases>5 then 'repeater' else 'non-repeater' end )as repeat_cust ,subscription_status,count(*) from customer group by repeat_cust ,subscription_status

--Q10. What is the revenue contribution of each age group? 
select age_group,sum(purchase_amount) from customer group by age_group
